#include <iostream>
using namespace std;

class Flyable {
public:
    virtual void fly() = 0;
    virtual ~Flyable() {}
};

class Swimmable {
public:
    virtual void swim() = 0;
    virtual ~Swimmable() {}
};

class Duck : public Flyable, public Swimmable {
public:
    void fly() override {
        cout << "Duck is flying" << endl;
    }

    void swim() override {
        cout << "Duck is swimming" << endl;
    }
};

int main() {
    Duck duck;
    duck.fly();
    duck.swim();
    return 0;
}

