interface Flyable {
    void fly(); // WHAT: something that can fly
}

interface Swimmable {
    void swim(); // WHAT: something that can swim
}

// Duck implements BOTH, something a single superclass could never do in Java
class Duck implements Flyable, Swimmable {
    private String name;

    Duck(String name) {
        this.name = name;
    }

    @Override
    public void fly() {
        System.out.println(name + " flies over the pond");
    }

    @Override
    public void swim() {
        System.out.println(name + " swims across the pond");
    }
}

public class Main {
    public static void main(String[] args) {
        Duck duck = new Duck("Donald");

        duck.fly();
        duck.swim();

        // Duck can be treated as EITHER interface independently
        Flyable flyer = duck;
        Swimmable swimmer = duck;
        flyer.fly();
        swimmer.swim();
    }
}

