from abc import ABC, abstractmethod


class Flyable(ABC):
    @abstractmethod
    def fly(self):
        pass  # WHAT: something that can fly


class Swimmable(ABC):
    @abstractmethod
    def swim(self):
        pass  # WHAT: something that can swim


# Duck implements BOTH, Python supports true multiple inheritance directly
class Duck(Flyable, Swimmable):
    def __init__(self, name):
        self.name = name

    def fly(self):
        print(f"{self.name} flies over the pond")

    def swim(self):
        print(f"{self.name} swims across the pond")


if __name__ == "__main__":
    duck = Duck("Donald")

    duck.fly()
    duck.swim()

