#include <iostream>
#include <string>
using namespace std;

class Flyable {
public:
    virtual void fly() = 0; // WHAT: something that can fly
    virtual ~Flyable() {}
};

class Swimmable {
public:
    virtual void swim() = 0; // WHAT: something that can swim
    virtual ~Swimmable() {}
};

// Duck implements BOTH, via C++'s native multiple inheritance
class Duck : public Flyable, public Swimmable {
private:
    string name;
public:
    Duck(string name) : name(name) {}

    void fly() override {
        cout << name << " flies over the pond" << endl;
    }

    void swim() override {
        cout << name << " swims across the pond" << endl;
    }
};

int main() {
    Duck duck("Donald");

    duck.fly();
    duck.swim();

    return 0;
}
